    private Map<String,String> files(File root)throws Exception{Map<String,String> result=new TreeMap<>();if(!root.exists())return result;try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){for(Path path:(Iterable<Path>)paths::iterator)if(Files.isRegularFile(path)){
        // AndroidX ProfileVerifier writes this exact compilation-status cache asynchronously, not app data.
        String relative=root.toPath().relativize(path).toString();if(relative.equals("profileInstalled"))continue;
        MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream input=Files.newInputStream(path)){byte[] block=new byte[8192];for(int n;(n=input.read(block))!=-1;)digest.update(block,0,n);}result.put(relative,Base64.getEncoder().encodeToString(digest.digest()));}}return result;}
    private void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(BackupActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,BackupActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(BackupActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}text("Backup");}
