        String utc=f.receipt(BackupExportReceipt.Kind.JSON).format(java.time.ZoneId.of("UTC"),Locale.US),hawaii=f.receipt(BackupExportReceipt.Kind.JSON).format(java.time.ZoneId.of("Pacific/Honolulu"),Locale.US);assertTrue(utc,utc.contains("Oct 29, 2026")&&utc.contains("(UTC)"));assertTrue(hawaii,hawaii.contains("Oct 28, 2026")&&hawaii.contains("(Pacific/Honolulu)"));assertEquals(Set.of("last_json_v1","last_csv_v1"),f.receiptPreferences.getAll().keySet());
