        f.restoreEntered=new CountDownLatch(1);f.restoreHold=new CountDownLatch(1);click("Review replacement");confirmation("Confirm backup replacement");assertTrue(f.restoreEntered.await(5,TimeUnit.SECONDS));text("Replacing local data…");capture("restoring");recreate();text("Replacing local data…");capture("restoring-recreated");assertEquals(1,f.retired);f.restoreHold.countDown();f.await(BackupJob.Phase.DONE);text("Data restored. Review and enable your alarms.");try(Store store=f.data.open()){assertFalse(store.alarm(92).enabled);assertEquals(NapPlan.Phase.CANCELLED,store.alarm(92).nap.phase);JSONObject event=f.data.event(store);assertEquals("speech",event.getString("user_category"));assertTrue(event.isNull("clip"));}assertFalse(f.data.file.exists());capture("restored");finish();launch();text("Data restored. Review and enable your alarms.");capture("result-reopened");assertEquals(1,f.retired);roomDimmingProfileRoundTrip();
